/** Synthetic local QA. No Telegram traffic, Keychain, Gmail, inference or external effects. */
import {createServer} from 'node:http';import {createInterface} from 'node:readline';import {openWorkspaceRuntime} from '../../src/runtime-source.js';import {WorkspaceApi,InMemoryWorkspaceRepository} from '../../src/workspace-api.js';import {handlePymesRequest} from '../../src/api-server.js';
import {TelegramStore} from '../../src/telegram-store.js';import {TelegramService} from '../../src/telegram-service.js';import {SyntheticTelegram,SyntheticTelegramVault,syntheticTelegramToken,telegramUpdate} from './telegram-fake.js';
const [dir,rawPort='8940']=process.argv.slice(2);if(!dir)throw new Error('QA_DIRECTORY_REQUIRED');const port=Number(rawPort);if(!Number.isInteger(port)||port<1024||port>65535)throw new Error('QA_INVALID_PORT');
const store=new TelegramStore(dir+'/telegram-inbox.db','telegram-qa','qa-owner'),vault=new SyntheticTelegramVault(),remote=new SyntheticTelegram();if(store.connection().credentialRef)await vault.set(store.connection().credentialRef!,syntheticTelegramToken);
remote.updates=[telegramUpdate(10,13201,'Hola, necesito preparar una propuesta para mi negocio.\nMensaje ficticio de QA.'),telegramUpdate(11,13201,'Corrección: podemos hablar mañana por la mañana.',true),telegramUpdate(12,555,'PRIVATE_DENIED_BODY'),telegramUpdate(13,13201,'<script>alert("QA")</script>\nEste texto debe verse literalmente, sin ejecutarse.')];
const telegram=new TelegramService(store,vault,remote.fetcher),runtime=await openWorkspaceRuntime(dir+'/runtime.db','telegram-qa',{telegram}),repo=new InMemoryWorkspaceRepository();repo.addSession('telegram-qa-token-123456789',{tenantId:'telegram-qa',userId:'qa-owner',role:'owner'});const api=new WorkspaceApi(repo,undefined,runtime.source);
const crm=runtime.source.crm!;for(const [id,name] of [['qa-person','Cliente de demostración'],['qa-business','Empresa de demostración']] as const)if(!crm.store.contact('qa-owner',id))crm.command('telegram-qa','qa-owner',{commandId:'qa-seed-'+id,expectedRevision:crm.store.revision('qa-owner'),operation:{type:'contact.create',id,name,email:'',phone:'',notes:'Ficha ficticia de QA.',relationship:'client'}});
const server=createServer(async(req,res)=>{try{const chunks:Buffer[]=[];for await(const b of req)chunks.push(Buffer.from(b));const body=Buffer.concat(chunks);const r=await handlePymesRequest(api,new Request(`http://127.0.0.1:${port}${req.url}`,{method:req.method,headers:req.headers as Record<string,string>,...(body.length?{body}:{})}),{allowedOrigins:['http://127.0.0.1:5181']});res.writeHead(r.status,Object.fromEntries(r.headers));res.end(await r.text());}catch{res.writeHead(500);res.end();}});
server.listen(port,'127.0.0.1',()=>console.log(JSON.stringify({qa:true,port,tenant:'telegram-qa',workspaceToken:'telegram-qa-token-123456789'})));
createInterface({input:process.stdin}).on('line',line=>{if(line==='error'){store.close();console.log('QA_TELEGRAM_STORE_CLOSED');}if(line==='crm-change'){const c=crm.store.contact('qa-owner','qa-person')!;crm.command('telegram-qa','qa-owner',{commandId:'qa-change-'+Date.now(),expectedRevision:crm.store.revision('qa-owner'),operation:{type:'contact.update',id:c.id,name:c.name,phone:c.phone,notes:'Actualización ficticia durante revisión.',relationship:c.relationship,status:c.status}});console.log('QA_CRM_CHANGED');}if(line==='identity-error'){runtime.source.telegramIdentities!.close();console.log('QA_IDENTITY_CLOSED');}if(line==='network'){remote.fail='network';console.log('QA_TELEGRAM_NETWORK_ERROR');}if(line==='stop'){server.close();runtime.close();void telegram.close().catch(()=>{});process.exit(0);}});
